export function useArray<T>(initial: T[]) {
  const [items, setItems] = useState(initial);
  return {
    items,
    push: (item: T) => setItems((prev: T[]) => [...prev, item]),
    removeAt: (index: number) => setItems((prev: T[]) => prev.filter((_, i) => i !== index)),
  };
