import { useReducer } from "react";

interface TodosState {
  text: string;
}

type TodosAction = { type: "ADD"; payload: string };

function reducer(state: TodosState, action: TodosAction): TodosState {
  switch (action.type) {
    case "ADD":
      return { ...state, text: action.payload };
    default:
      return state;
  }
}

interface TodosPanelProps {
  initial: string;
}

export function TodosPanel({ initial }: TodosPanelProps) {
  const [state, dispatch] = useReducer(reducer, { text: initial });
  return (
    <button
      type="button"
      onClick={() => dispatch({ type: "ADD", payload: "updated" })}
    >
      {state.text}
    </button>
  );
}
```

